 hadiths=[
  dict(ar="كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُومُ مِنَ اللَّيْلِ حَتَّى تَتَفَطَّرَ قَدَمَاهُ، فَقَالَتْ عَائِشَةُ: لِمَ تَصْنَعُ هَذَا وَقَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ? قَالَ: أَفَلَا أَكُونُ عَبْدًا شَكُورًا", en="The Prophet ﷺ stood in night prayer until his feet swelled. Aisha asked why — his past and future sins were already forgiven! He said: \"Should I not be a grateful servant?\"", ref="Sahih al-Bukhari 4837 · Sahih Muslim 2820 — gratitude is an ACT, not a mood"),
  dict(ar="لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ", en="\"He does not thank Allah who does not thank people.\"", ref="Sunan Abi Dawud 4811 · Jami' at-Tirmidhi 1954, graded sahih by al-Albani (verified at hadeethenc.com #66255)"),
 ],
 proph_post=["First hadith: gratitude had a BODY — night prayer until his feet ached. Shukr is not a poster on the wall; it is what you DO with what you were given. Second hadith: thank the humans too — Mama's cooking, Huda's hugs — the same worship, pointed at people."],
 grid2=[dict(h="Fake shukr", p="\"Everything is great! Nothing hurts!\" (while swallowing the pain in silence)"),
        dict(h="Honest shukr", p="\"My heart hurts — AND — this good thing is real, and both belong to Allah.\"")],
